// ─────────────────────────────────────────────────────────────────────────
// SYNC LICENSING DISCOVERY — connect a real data source here:
//   A sync licensing database / music supervisor directory (e.g. via
//   SYNC_LICENSING_API_KEY — add the vendor of your choice)
// Until connected this reports 'partial' with the missing credential — it
// does not fabricate film/TV/game/ad opportunities or agency contacts.
// Credential values are injected upstream by the 'Load Credential Flags'
// node (Set node expressions) since Code nodes cannot access $env directly.
// ─────────────────────────────────────────────────────────────────────────
const input = $input.first().json;
const missing = [];
if (!input.SYNC_LICENSING_API_KEY) missing.push('SYNC_LICENSING_API_KEY');

return [{ json: {
  mission_id: input.mission_id,
  execution_id: input.execution_id,
  status: missing.length ? 'partial' : 'completed',
  summary: missing.length ? `Sync Intelligence ready — waiting on: ${missing.join(', ')}` : 'Sync opportunity discovery complete',
  results: {
    film_opportunities: null,
    tv_opportunities: null,
    games: null,
    ads: null,
    music_supervisors: null,
    sync_agencies: null,
    licensing_targets: null,
    missing_credentials: missing,
  },
} }];
